1	import { Overlay, OverlayRef } from '@angular/cdk/overlay';
2	import { ComponentPortal } from '@angular/cdk/portal';
3	import { AsyncPipe, CommonModule } from '@angular/common';
4	import {
5	    Component,
6	    HostListener,
7	    Injector,
8	    OnDestroy,
9	    OnInit,
10	    computed,
11	    effect,
12	    inject,
13	    signal,
14	} from '@angular/core';
15	import { toSignal } from '@angular/core/rxjs-interop';
16	import { ActivatedRoute, Router } from '@angular/router';
17	import { Store } from '@ngrx/store';
18	import { StorageMap } from '@ngx-pwa/local-storage';
19	import { TranslatePipe } from '@ngx-translate/core';
20	import { ResizableDirective } from 'components';
21	import { isM3uCatchupPlaybackSupported } from 'm3u-utils';
22	import { PlaylistContextFacade } from '@iptvnator/playlist/shared/util';
23	import {
24	    COMPONENT_OVERLAY_REF,
25	    EpgListComponent,
26	    MultiEpgContainerComponent,
27	} from '@iptvnator/ui/epg';
28	import {
29	    ChannelActions,
30	    PlaylistActions,
31	    selectActive,
32	    selectActivePlaybackUrl,
33	    selectChannels,
34	    selectChannelsLoading,
35	    selectCurrentEpgProgram,
36	} from 'm3u-state';
37	import {
38	    firstValueFrom,
39	    Observable,
40	    Subscription,
41	    combineLatest,
42	    combineLatestWith,
43	    distinctUntilChanged,
44	    filter,
45	    map,
46	    startWith,
47	    switchMap,
48	    take,
49	} from 'rxjs';
50	import {
51	    getAdjacentChannelItem,
52	    getChannelItemByNumber,
53	    isWorkspaceLayoutRoute,
54	    PORTAL_EXTERNAL_PLAYBACK,
55	    WorkspaceHeaderContextService,
56	} from '@iptvnator/portal/shared/util';
57	import { PortalEmptyStateComponent } from '@iptvnator/portal/shared/ui';
58	import {
59	    ArtPlayerComponent,
60	    AudioPlayerComponent,
61	    HtmlVideoPlayerComponent,
62	    SidebarComponent,
63	    VjsPlayerComponent,
64	} from '@iptvnator/ui/playback';
65	import { ChannelListLoadingStateComponent } from 'components';
66	import { DataService, PlaylistsService, SettingsStore } from 'services';
67	import {
68	    Channel,
69	    EpgProgram,
70	    ExternalPlayerSession,
71	    PLAYLIST_PARSE_BY_URL,
72	    M3uRecentlyViewedItem,
73	    PlaylistMeta,
74	    STORE_KEY,
75	    Settings,
76	    VideoPlayer,
77	} from 'shared-interfaces';
78	
79	const M3U_MULTI_EPG_HEADER_ACTION_ID = 'm3u-multi-epg';
80	const M3U_SIDEBAR_STORAGE_KEY = 'm3u-sidebar-width';
81	const M3U_GROUPS_SIDEBAR_STORAGE_KEY = 'm3u-groups-sidebar-width';
82	const M3U_SIDEBAR_MIN_WIDTH = 200;
83	const M3U_SIDEBAR_MAX_WIDTH = 600;
84	const M3U_SIDEBAR_DEFAULT_WIDTH = 460;
85	
86	@Component({
87	    selector: 'app-video-player',
88	    imports: [
89	        ArtPlayerComponent,
90	        AsyncPipe,
91	        AudioPlayerComponent,
92	        ChannelListLoadingStateComponent,
93	        CommonModule,
94	        EpgListComponent,
95	        HtmlVideoPlayerComponent,
96	        PortalEmptyStateComponent,
97	        ResizableDirective,
98	        SidebarComponent,
99	        TranslatePipe,
100	        VjsPlayerComponent,
101	    ],
102	    templateUrl: './video-player.component.html',
103	    styleUrl: './video-player.component.scss',
104	})
105	export class VideoPlayerComponent implements OnInit, OnDestroy {
106	    private readonly activatedRoute = inject(ActivatedRoute);
107	    private readonly dataService = inject(DataService);
108	    private readonly overlay = inject(Overlay);
109	    private readonly playlistsService = inject(PlaylistsService);
110	    private readonly playlistContext = inject(PlaylistContextFacade);
111	    private readonly router = inject(Router);
112	    private readonly settingsStore = inject(SettingsStore);
113	    private readonly storage = inject(StorageMap);
114	    private readonly store = inject(Store);
115	    private readonly externalPlayback = inject(PORTAL_EXTERNAL_PLAYBACK);
116	    private readonly workspaceHeaderContext = inject(
117	        WorkspaceHeaderContextService
118	    );
119	
120	    /** Active selected channel */
121	    readonly activeChannel = this.store.selectSignal(selectActive);
122	    readonly activePlaybackUrl = this.store.selectSignal(
123	        selectActivePlaybackUrl
124	    );
125	    readonly activePlaylistId = this.playlistContext.resolvedPlaylistId;
126	    readonly channels = this.store.selectSignal(selectChannels);
127	    readonly channelsLoading = this.store.selectSignal(selectChannelsLoading);
128	    readonly archivePlaybackAvailable = computed(() =>
129	        isM3uCatchupPlaybackSupported(this.activeChannel())
130	    );
131	    readonly playbackChannel = computed<Channel | null>(() => {
132	        const activeChannel = this.activeChannel();
133	        if (!activeChannel) {
134	            return null;
135	        }
136	
137	        const playbackUrl = this.activePlaybackUrl();
138	        if (!playbackUrl) {
139	            return activeChannel;
140	        }
141	
142	        return {
143	            ...activeChannel,
144	            url: playbackUrl,
145	            epgParams: '',
146	        } as Channel;
147	    });
148	    readonly sidebarStorageKey = computed(() =>
149	        this.activeView() === 'groups'
150	            ? M3U_GROUPS_SIDEBAR_STORAGE_KEY
151	            : M3U_SIDEBAR_STORAGE_KEY
152	    );
153	    readonly sidebarWidth = signal(M3U_SIDEBAR_DEFAULT_WIDTH);
154	    readonly sidebarMinWidth = M3U_SIDEBAR_MIN_WIDTH;
155	    readonly sidebarMaxWidth = M3U_SIDEBAR_MAX_WIDTH;
156	
157	    /** Channels list */
158	    readonly channels$: Observable<Channel[]> = this.store.select(
159	        selectChannels
160	    ) as Observable<Channel[]>;
161	
162	    /** Current epg program */
163	    readonly epgProgram = this.store.selectSignal(selectCurrentEpgProgram);
164	
165	    /** Active M3U view (all, groups, favorites, recent) */
166	    readonly activeView = toSignal(
167	        this.activatedRoute.params.pipe(
168	            map((params) => params['view'] || 'all')
169	        ),
170	        { initialValue: 'all' }
171	    );
172	
173	    /** Selected video player options */
174	    playerSettings: Partial<Settings> = {
175	        player: VideoPlayer.VideoJs,
176	        showCaptions: false,
177	    };
178	
179	    readonly isDesktop = !!window['electron'];
180	    readonly isWorkspaceLayout = isWorkspaceLayoutRoute(this.activatedRoute);
181	
182	    /** EPG overlay reference */
183	    private overlayRef!: OverlayRef;
184	    private unsubscribeRemoteChannelChange?: () => void;
185	    private unsubscribeRemoteCommand?: () => void;
186	    private statusSubscription?: Subscription;
187	    private lastKnownVolume = 1;
188	    private lastRecordedRecentKey = '';
189	    private lastExternalSessionStateKey = this.getExternalSessionStateKey(
190	        this.externalPlayback.activeSession()
191	    );
192	
193	    /** Channel number input state */
194	    channelNumberInput = '';
195	    showChannelNumberOverlay = false;
196	    private channelNumberTimeout?: number;
197	
198	    volume = 1;
199	
200	    constructor() {
201	        // Initialize volume from localStorage in constructor
202	        const savedVolume = localStorage.getItem('volume');
203	        if (savedVolume !== null) {
204	            this.volume = Number(savedVolume);
205	        }
206	
207	        // React to settings changes
208	        effect(() => {
209	            this.playerSettings = {
210	                player: this.settingsStore.player(),
211	                showCaptions: this.settingsStore.showCaptions(),
212	            };
213	        });
214	
215	        effect(() => {
216	            this.sidebarWidth.set(
217	                this.loadSidebarWidth(this.sidebarStorageKey())
218	            );
219	        });
220	
221	        effect(() => {
222	            const playlistId = this.activePlaylistId();
223	            const activeChannel = this.activeChannel();
224	
225	            if (!playlistId || !activeChannel?.url) {
226	                return;
227	            }
228	
229	            const nextKey = `${playlistId}::${activeChannel.url}`;
230	            if (this.lastRecordedRecentKey === nextKey) {
231	                return;
232	            }
233	
234	            this.lastRecordedRecentKey = nextKey;
235	            void this.persistRecentlyViewedChannel(playlistId, activeChannel);
236	        });
237	
238	        effect(() => {
239	            const currentView = this.activeView();
240	            const channels = this.channels();
241	            const activeChannel = this.activeChannel();
242	            const state =
243	                this.router.currentNavigation()?.extras?.state ??
244	                window.history.state;
245	            const targetUrl =
246	                typeof state?.openRecentChannelUrl === 'string'
247	                    ? state.openRecentChannelUrl.trim()
248	                    : '';
249	
250	            if (
251	                currentView !== 'recent' ||
252	                !targetUrl ||
253	                channels.length === 0
254	            ) {
255	                return;
256	            }
257	
258	            if (activeChannel?.url === targetUrl) {
259	                this.clearConsumedRecentChannelState();
260	                return;
261	            }
262	
263	            const matchedChannel = channels.find(
264	                (channel) => channel.url === targetUrl
265	            );
266	            if (!matchedChannel) {
267	                return;
268	            }
269	
270	            this.store.dispatch(
271	                ChannelActions.setActiveChannel({ channel: matchedChannel })
272	            );
273	            this.clearConsumedRecentChannelState();
274	        });
275	
276	        effect(() => {
277	            const player = this.settingsStore.player();
278	            const session = this.externalPlayback.activeSession();
279	            const activeChannel = this.activeChannel();
280	            const sessionStateKey = this.getExternalSessionStateKey(session);
281	
282	            if (sessionStateKey === this.lastExternalSessionStateKey) {
283	                return;
284	            }
285	
286	            this.lastExternalSessionStateKey = sessionStateKey;
287	
288	            if (
289	                !activeChannel ||
290	                !this.isExternalPlayer(player) ||
291	                !this.isTerminalExternalSession(session)
292	            ) {
293	                return;
294	            }
295	
296	            this.store.dispatch(ChannelActions.resetActiveChannel());
297	        });
298	    }
299	
300	    /**
301	     * Sets video player and subscribes to channel list from the store
302	     */
303	    ngOnInit(): void {
304	        this.applySettings();
305	        this.getPlaylistUrlAsParam();
306	        this.registerHeaderShortcut();
307	
308	        // Setup remote control channel change listener (Electron only)
309	        if (this.isDesktop && window.electron?.onChannelChange) {
310	            const unsubscribe = window.electron.onChannelChange(
311	                (data: { direction: 'up' | 'down' }) => {
312	                    this.handleRemoteChannelChange(data.direction);
313	                }
314	            );
315	            if (typeof unsubscribe === 'function') {
316	                this.unsubscribeRemoteChannelChange = unsubscribe;
317	            }
318	        }
319	        if (this.isDesktop && window.electron?.onRemoteControlCommand) {
320	            const unsubscribe = window.electron.onRemoteControlCommand(
321	                (command) => {
322	                    this.handleRemoteControlCommand(command);
323	                }
324	            );
325	            if (typeof unsubscribe === 'function') {
326	                this.unsubscribeRemoteCommand = unsubscribe;
327	            }
328	        }
329	
330	        this.statusSubscription = combineLatest([
331	            this.channels$,
332	            this.store.select(selectActive),
333	            this.store.select(selectCurrentEpgProgram).pipe(startWith(null)),
334	        ]).subscribe(([channels, activeChannel, epgProgram]) => {
335	            if (!window.electron?.updateRemoteControlStatus || !activeChannel) {
336	                return;
337	            }
338	
339	            const currentEpgProgram = epgProgram as
340	                | EpgProgram
341	                | null
342	                | undefined;
343	            const currentIndex = channels.findIndex(
344	                (channel) => channel.url === activeChannel.url
345	            );
346	
347	            window.electron.updateRemoteControlStatus({
348	                portal: 'm3u',
349	                isLiveView: true,
350	                channelName: activeChannel.name ?? activeChannel.tvg?.name,
351	                channelNumber: currentIndex >= 0 ? currentIndex + 1 : undefined,
352	                epgTitle: currentEpgProgram?.title,
353	                epgStart: currentEpgProgram?.start,
354	                epgEnd: currentEpgProgram?.stop,
355	                supportsVolume: true,
356	                volume: this.volume,
357	                muted: this.volume === 0,
358	            });
359	        });
360	    }
361	
362	    /**
363	     * Handle remote control channel change
364	     */
365	    handleRemoteChannelChange(direction: 'up' | 'down'): void {
366	        console.log(`Remote control: changing channel ${direction}`);
367	
368	        // Use combineLatest to get both values and take only the first emission
369	        combineLatest([this.channels$, this.store.select(selectActive)])
370	            .pipe(
371	                filter(([channels, activeChannel]) => {
372	                    return channels.length > 0 && !!activeChannel;
373	                }),
374	                take(1),
375	                map(([channels, activeChannel]) => {
376	                    return {
377	                        channels,
378	                        activeChannel: activeChannel as Channel,
379	                    };
380	                })
381	            )
382	            .subscribe({
383	                next: ({ channels, activeChannel }) => {
384	                    const nextChannel = getAdjacentChannelItem(
385	                        channels,
386	                        activeChannel.url,
387	                        direction,
388	                        (channel) => channel.url
389	                    );
390	
391	                    if (!nextChannel) {
392	                        return;
393	                    }
394	
395	                    this.store.dispatch(
396	                        ChannelActions.setActiveChannel({
397	                            channel: nextChannel,
398	                        })
399	                    );
400	                },
401	                error: (err) => {
402	                    console.error('Error changing channel:', err);
403	                },
404	            });
405	    }
406	
407	    ngOnDestroy(): void {
408	        this.workspaceHeaderContext.clearAction(M3U_MULTI_EPG_HEADER_ACTION_ID);
409	        this.unsubscribeRemoteChannelChange?.();
410	        this.unsubscribeRemoteCommand?.();
411	        this.statusSubscription?.unsubscribe();
412	    }
413	
414	    onSidebarWidthChange(width: number): void {
415	        this.sidebarWidth.set(this.clampSidebarWidth(width));
416	    }
417	
418	    onSidebarResizeEnd(width: number): void {
419	        this.persistSidebarWidth(this.sidebarStorageKey(), width);
420	    }
421	
422	    onGroupedSidebarWidthRequested(width: number): void {
423	        this.sidebarWidth.set(this.clampSidebarWidth(width));
424	    }
425	
426	    onGroupedSidebarWidthRequestEnded(width: number): void {
427	        this.persistSidebarWidth(this.sidebarStorageKey(), width);
428	    }
429	
430	    /**
431	     * Opens a playlist provided as a url param
432	     * e.g. iptvnat.or?url=http://...
433	     * @pwaOnly
434	     */
435	    getPlaylistUrlAsParam() {
436	        const URL_REGEX = /^(http|https|file):\/\/[^ "]+$/;
437	        const playlistUrl = this.activatedRoute.snapshot.queryParams['url'];
438	
439	        if (playlistUrl && playlistUrl.match(URL_REGEX)) {
440	            this.dataService.sendIpcEvent(PLAYLIST_PARSE_BY_URL, {
441	                url: playlistUrl,
442	                isTemporary: true,
443	            });
444	        }
445	    }
446	
447	    /**
448	     * Reads the app configuration from the browsers storage and applies the settings in the current component
449	     */
450	    applySettings(): void {
451	        this.storage.get(STORE_KEY.Settings).subscribe((settings: unknown) => {
452	            if (settings && Object.keys(settings as Settings).length > 0) {
453	                this.playerSettings = {
454	                    player:
455	                        (settings as Settings).player || VideoPlayer.VideoJs,
456	                    showCaptions: (settings as Settings).showCaptions || false,
457	                };
458	            }
459	        });
460	    }
461	
462	    private loadSidebarWidth(storageKey: string): number {
463	        const fallbackKey =
464	            storageKey === M3U_GROUPS_SIDEBAR_STORAGE_KEY
465	                ? M3U_SIDEBAR_STORAGE_KEY
466	                : '';
467	        const storedWidth = Number.parseInt(
468	            localStorage.getItem(storageKey) ??
469	                (fallbackKey ? localStorage.getItem(fallbackKey) : '') ??
470	                '',
471	            10
472	        );
473	
474	        return this.clampSidebarWidth(
475	            Number.isNaN(storedWidth)
476	                ? M3U_SIDEBAR_DEFAULT_WIDTH
477	                : storedWidth
478	        );
479	    }
480	
481	    private persistSidebarWidth(storageKey: string, width: number): void {
482	        const clampedWidth = this.clampSidebarWidth(width);
483	        this.sidebarWidth.set(clampedWidth);
484	        localStorage.setItem(storageKey, clampedWidth.toString());
485	    }
486	
487	    private clampSidebarWidth(width: number): number {
488	        return Math.max(
489	            M3U_SIDEBAR_MIN_WIDTH,
490	            Math.min(M3U_SIDEBAR_MAX_WIDTH, width)
491	        );
492	    }
493	
494	    private async persistRecentlyViewedChannel(
495	        playlistId: string,
496	        channel: Channel
497	    ): Promise<void> {
498	        const recentlyViewedItem: M3uRecentlyViewedItem = {
499	            source: 'm3u',
500	            id: channel.url,
501	            url: channel.url,
502	            title: channel.name?.trim() || channel.tvg?.name || channel.url,
503	            channel_id: channel.id,
504	            poster_url: channel.tvg?.logo || undefined,
505	            tvg_id: channel.tvg?.id || undefined,
506	            tvg_name: channel.tvg?.name || undefined,
507	            group_title: channel.group?.title || undefined,
508	            category_id: 'live',
509	            added_at: new Date().toISOString(),
510	        };
511	
512	        const updatedPlaylist = await firstValueFrom(
513	            this.playlistsService.addM3uRecentlyViewed(
514	                playlistId,
515	                recentlyViewedItem
516	            )
517	        );
518	
519	        this.store.dispatch(
520	            PlaylistActions.updatePlaylistMeta({
521	                playlist: {
522	                    _id: playlistId,
523	                    recentlyViewed: updatedPlaylist?.recentlyViewed ?? [],
524	                } as PlaylistMeta,
525	            }) as any
526	        );
527	    }
528	
529	    private clearConsumedRecentChannelState(): void {
530	        const historyState = (window.history.state ?? {}) as Record<
531	            string,
532	            unknown
533	        >;
534	        if (!historyState['openRecentChannelUrl']) {
535	            return;
536	        }
537	
538	        try {
539	            const nextState = { ...historyState };
540	            delete nextState['openRecentChannelUrl'];
541	            window.history.replaceState(nextState, document.title);
542	        } catch {
543	            // no-op
544	        }
545	    }
546	
547	    /**
548	     * Opens the overlay with multi EPG view
549	     */
550	    openMultiEpgView(): void {
551	        const positionStrategy = this.overlay
552	            .position()
553	            .global()
554	            .centerHorizontally()
555	            .centerVertically();
556	
557	        this.overlayRef = this.overlay.create({
558	            hasBackdrop: true,
559	            positionStrategy,
560	            width: '100%',
561	            height: '100%',
562	        });
563	
564	        const injector = Injector.create({
565	            providers: [
566	                {
567	                    provide: COMPONENT_OVERLAY_REF,
568	                    useValue: this.overlayRef,
569	                },
570	            ],
571	        });
572	
573	        const portal = new ComponentPortal(
574	            MultiEpgContainerComponent,
575	            null,
576	            injector
577	        );
578	
579	        const componentRef = this.overlayRef.attach(portal);
580	        componentRef.instance.playlistChannels = this.store.select(
581	            selectChannels
582	        ) as Observable<Channel[]>;
583	
584	        // Pass the active channel's tvg.id for highlighting
585	        const currentChannel = this.activeChannel();
586	        if (currentChannel) {
587	            componentRef.instance.activeChannelId =
588	                currentChannel.tvg?.id || null;
589	        }
590	
591	        this.overlayRef.backdropClick().subscribe(() => {
592	            this.overlayRef.dispose();
593	        });
594	    }
595	
596	    @HostListener('document:keydown', ['$event'])
597	    handleKeyPress(event: KeyboardEvent): void {
598	        // Only handle digit keys (0-9)
599	        if (event.key >= '0' && event.key <= '9') {
600	            // Don't trigger hotkeys when user is typing in input fields
601	            if (this.isTypingInInput(event)) {
602	                return;
603	            }
604	            event.preventDefault();
605	            this.handleChannelNumberInput(event.key);
606	        }
607	    }
608	
609	    /**
610	     * Handle channel number input from keyboard
611	     * Debounces input to allow multi-digit channel numbers
612	     */
613	    handleChannelNumberInput(digit: string): void {
614	        // Clear existing timeout
615	        if (this.channelNumberTimeout) {
616	            clearTimeout(this.channelNumberTimeout);
617	        }
618	
619	        // Add digit to current input
620	        this.channelNumberInput += digit;
621	        this.showChannelNumberOverlay = true;
622	
623	        // Set timeout to switch channel after 2 seconds of no input
624	        this.channelNumberTimeout = window.setTimeout(() => {
625	            this.switchToChannelByNumber(parseInt(this.channelNumberInput, 10));
626	            this.clearChannelNumberInput();
627	        }, 2000);
628	    }
629	
630	    /**
631	     * Switch to channel by number (1-based index)
632	     */
633	    switchToChannelByNumber(channelNumber: number): void {
634	        this.channels$
635	            .pipe(
636	                take(1),
637	                map((channels) =>
638	                    getChannelItemByNumber(channels, channelNumber)
639	                )
640	            )
641	            .subscribe((channel) => {
642	                if (channel) {
643	                    this.store.dispatch(
644	                        ChannelActions.setActiveChannel({ channel })
645	                    );
646	                }
647	            });
648	    }
649	
650	    /**
651	     * Clear channel number input and hide overlay
652	     */
653	    clearChannelNumberInput(): void {
654	        this.channelNumberInput = '';
655	        this.showChannelNumberOverlay = false;
656	        if (this.channelNumberTimeout) {
657	            clearTimeout(this.channelNumberTimeout);
658	            this.channelNumberTimeout = undefined;
659	        }
660	    }
661	
662	    /**
663	     * Check if the user is currently typing in an input or textarea field
664	     * @param event Keyboard event
665	     * @returns true if the event target is an input or textarea element
666	     */
667	    private isTypingInInput(event: Event): boolean {
668	        const target = event.target;
669	        return (
670	            target instanceof HTMLInputElement ||
671	            target instanceof HTMLTextAreaElement
672	        );
673	    }
674	
675	    private handleRemoteControlCommand(command: {
676	        type:
677	            | 'channel-select-number'
678	            | 'volume-up'
679	            | 'volume-down'
680	            | 'volume-toggle-mute';
681	        number?: number;
682	    }): void {
683	        if (command.type === 'channel-select-number' && command.number) {
684	            this.switchToChannelByNumber(command.number);
685	            return;
686	        }
687	
688	        if (command.type === 'volume-up') {
689	            this.setVolume(this.volume + 0.1);
690	        } else if (command.type === 'volume-down') {
691	            this.setVolume(this.volume - 0.1);
692	        } else if (command.type === 'volume-toggle-mute') {
693	            if (this.volume === 0) {
694	                this.setVolume(this.lastKnownVolume || 1);
695	            } else {
696	                this.lastKnownVolume = this.volume;
697	                this.setVolume(0);
698	            }
699	        }
700	    }
701	
702	    private setVolume(next: number): void {
703	        const clamped = Math.max(0, Math.min(1, Number(next.toFixed(2))));
704	        this.volume = clamped;
705	        if (clamped > 0) {
706	            this.lastKnownVolume = clamped;
707	        }
708	        localStorage.setItem('volume', String(clamped));
709	
710	        if (window.electron?.updateRemoteControlStatus) {
711	            window.electron.updateRemoteControlStatus({
712	                portal: 'm3u',
713	                isLiveView: true,
714	                supportsVolume: true,
715	                volume: this.volume,
716	                muted: this.volume === 0,
717	            });
718	        }
719	    }
720	
721	    shouldShowInlinePlayer(channel: Channel | null | undefined): boolean {
722	        if (!channel) {
