1	import { CommonModule } from '@angular/common';
2	import {
3	    ChangeDetectionStrategy,
4	    Component,
5	    computed,
6	    inject,
7	    Input,
8	    input,
9	    OnDestroy,
10	    OnInit,
11	    output,
12	    signal,
13	} from '@angular/core';
14	import { toSignal } from '@angular/core/rxjs-interop';
15	import { MatButtonModule } from '@angular/material/button';
16	import { MatIconModule } from '@angular/material/icon';
17	import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
18	import { Store } from '@ngrx/store';
19	import { StorageMap } from '@ngx-pwa/local-storage';
20	import { TranslatePipe } from '@ngx-translate/core';
21	import { EpgService } from '@iptvnator/epg/data-access';
22	import { PlaylistContextFacade } from '@iptvnator/playlist/shared/util';
23	import {
