61	function groupChannelsByTitle(channels: Channel[]): Record<string, Channel[]> {
62	    return channels.reduce<Record<string, Channel[]>>((groups, channel) => {
63	        const key = channel.group?.title ?? '';
64	        if (!groups[key]) {
65	            groups[key] = [];
66	        }
67	        groups[key].push(channel);
68	        return groups;
69	    }, {});
70	}
71	
72	@Component({
73	    selector: 'app-channel-list-container',
74	    templateUrl: './channel-list-container.component.html',
75	    styleUrls: ['./channel-list-container.component.scss'],
76	    changeDetection: ChangeDetectionStrategy.OnPush,
77	    imports: [
78	        AllChannelsViewComponent,
79	        ChannelListLoadingStateComponent,
80	        CommonModule,
81	        FavoritesViewComponent,
82	        GroupsViewComponent,
83	        MatButtonModule,
84	        MatIconModule,
85	        RecentViewComponent,
86	        TranslatePipe,
87	    ],
88	})
89	export class ChannelListContainerComponent implements OnInit, OnDestroy {
90	    private readonly epgService = inject(EpgService);
91	    private readonly playlistsService = inject(PlaylistsService);
92	    private readonly storage = inject(StorageMap);
93	    private readonly store = inject(Store);
94	    private readonly router = inject(Router);
95	    private readonly route = inject(ActivatedRoute);
96	    private readonly playlistContext = inject(PlaylistContextFacade);
97	
98	    /** Map of channel ID to current EPG program */
99	    readonly channelEpgMap = signal(new Map<string, EpgProgram | null>());
100	
101	    /** Interval for refreshing EPG data */
102	    private epgRefreshInterval?: number;
103	
104	    /** Global progress tick signal - triggers re-computation of progress percentages */
105	    readonly progressTick = signal(0);
106	
107	    /** Interval for global progress updates */
108	    private progressInterval?: number;
109	
110	    /** Whether to show EPG data in channel items */
111	    readonly shouldShowEpg = signal(false);
112	
113	    /** Item size for virtual scroll - compact when no EPG */
114	    readonly itemSize = computed(() => (this.shouldShowEpg() ? 68 : 48));
115	
116	    /** Active view (all, groups, favorites, recent) */
117	    readonly activeView = input<string>('all');
118	    readonly channelsLoading = input(false);
119	    readonly recentItems = input<PlaylistRecentlyViewedItem[]>([]);
120	    readonly sidebarWidth = input<number | null>(null);
121	    readonly sidebarWidthRequested = output<number>();
122	    readonly sidebarWidthRequestEnded = output<number>();
123	    readonly isWorkspaceLayout = isWorkspaceLayoutRoute(this.route);
124	    private readonly routeSearchTerm = queryParamSignal(
125	        this.route,
126	        'q',
127	        (value) => (value ?? '').trim().toLowerCase()
128	    );
129	    readonly workspaceSearchTerm = computed(() =>
130	        this.isWorkspaceLayout ? this.routeSearchTerm() : ''
131	    );
132	
133	    readonly currentUrl = toSignal(
134	        this.router.events.pipe(
135	            filter((event) => event instanceof NavigationEnd),
136	            map((event) => (event as NavigationEnd).urlAfterRedirects)
137	        ),
138	        { initialValue: this.router.url }
139	    );
140	
141	    readonly viewTitle = computed(() => {
142	        const view = this.activeView();
143	        const url = this.currentUrl();
144	        if (view === 'all') return 'CHANNELS.ALL_CHANNELS';
145	        if (view === 'groups') return 'CHANNELS.GROUPS';
146	        if (view === 'recent') return 'PORTALS.SIDEBAR.RECENT';
147	        if (view === 'favorites') {
148	            return url.includes('/workspace/global-favorites')
149	                ? 'HOME.PLAYLISTS.GLOBAL_FAVORITES'
150	                : 'CHANNELS.FAVORITES';
151	        }
152	        return '';
153	    });
154	
155	    /** Channels array */
156	    _channelList: Channel[] = [];
157	    private readonly channelListSignal = signal<Channel[]>([]);
158	    private channelList$ = new BehaviorSubject<Channel[]>([]);
159	
160	    get channelList(): Channel[] {
161	        return this._channelList;
162	    }
163	
164	    @Input()
165	    set channelList(value: Channel[]) {
166	        const safeValue = value ?? [];
167	        this._channelList = safeValue;
168	        this.channelListSignal.set(safeValue);
169	        this.channelList$.next(safeValue);
170	        this.fetchEpgForChannels(safeValue);
171	    }
172	
173	    /** Route-aware playlist ID for recent-item mutations */
174	    private readonly resolvedPlaylistId = this.playlistContext.resolvedPlaylistId;
175	    private readonly activePlaylist = this.playlistContext.activePlaylist;
176	
177	    readonly hiddenGroupTitles = computed(() => {
178	        const playlist = this.activePlaylist();
179	
180	        if (!playlist || playlist.serverUrl || playlist.macAddress) {
181	            return [];
182	        }
183	
184	        return playlist.hiddenGroupTitles ?? [];
185	    });
186	
187	    /** Displayed channels - filters out unfavorited channels in global favorites view */
188	    readonly displayedChannels = computed(() => {
189	        return this.channelListSignal();
190	    });
191	
192	    /** Object with channels sorted by groups */
193	    readonly groupedChannels = computed(() =>
194	        groupChannelsByTitle(this.displayedChannels())
195	    );
196	
197	    readonly recentChannelItems = computed<RecentViewItem[]>(() => {
198	        const channels = this.channelListSignal();
199	        const recentItems = this.recentItems();
200	        const channelsByUrl = new Map(
201	            channels.map((channel) => [channel.url, channel] as const)
202	        );
203	        const channelsById = new Map(
204	            channels.map((channel) => [channel.id, channel] as const)
205	        );
206	        const seenUrls = new Set<string>();
207	
208	        return [...recentItems]
209	            .filter(isM3uRecentlyViewedItem)
210	            .sort(
211	                (a, b) =>
212	                    new Date(normalizeStalkerDate(b.added_at)).getTime() -
213	                    new Date(normalizeStalkerDate(a.added_at)).getTime()
214	            )
215	            .reduce<RecentViewItem[]>((acc, item) => {
216	                const channelUrl = item.url?.trim();
217	                if (!channelUrl || seenUrls.has(channelUrl)) {
218	                    return acc;
219	                }
220	
221	                const channel =
222	                    channelsByUrl.get(channelUrl) ||
223	                    (item.channel_id
224	                        ? channelsById.get(item.channel_id)
225	                        : undefined);
226	
227	                if (!channel) {
228	                    return acc;
229	                }
230	
231	                seenUrls.add(channel.url);
232	                acc.push({
233	                    channel,
234	                    viewedAt: normalizeStalkerDate(item.added_at),
235	                });
236	                return acc;
237	            }, []);
238	    });
239	
240	    /** Selected channel */
241	    readonly activeChannel = this.store.selectSignal(selectActive);
242	
243	    /** Active channel URL for highlighting */
244	    readonly activeChannelUrl = computed(() => this.activeChannel()?.url);
245	
246	    /** Set of favorite channel URLs for quick lookup */
247	    private readonly _favorites = this.store.selectSignal(selectFavorites);
248	    readonly favoriteIds = computed(() => new Set(this._favorites()));
249	
250	    /** List with favorites */
251	    favorites$ = combineLatest([
252	        this.store.select(selectFavorites),
253	        this.channelList$,
254	    ]).pipe(
255	        map(([favoriteChannelIds, channelList]) => {
256	            return favoriteChannelIds
257	                .map((favoriteChannelId) =>
258	                    channelList.find(
259	                        (channel) => channel.url === favoriteChannelId
260	                    )
261	                )
262	                .filter((channel): channel is Channel => channel !== undefined);
263	        })
264	    );
265	
266	    ngOnInit(): void {
267	        // Check if EPG should be shown (only in Electron with configured EPG URL)
268	        const isElectron = !!window['electron'];
269	        if (isElectron) {
270	            this.storage
271	                .get(STORE_KEY.Settings)
272	                .subscribe((settings: unknown) => {
273	                    if (
274	                        settings &&
275	                        Object.keys(settings as Settings).length > 0
276	                    ) {
277	                        const epgUrl = (settings as Settings).epgUrl;
278	                        this.shouldShowEpg.set(!!(epgUrl && epgUrl.length > 0));
279	                    }
280	                });
281	        } else {
282	            this.shouldShowEpg.set(false);
283	        }
284	
285	        // Set up EPG refresh interval (every 60 seconds)
286	        this.epgRefreshInterval = window.setInterval(() => {
287	            this.fetchEpgForChannels(this._channelList);
288	        }, 60000);
289	
290	        // Set up global progress update interval (every 30 seconds)
291	        this.progressInterval = window.setInterval(() => {
292	            this.progressTick.update((v) => v + 1);
293	        }, 30000);
294	    }
295	
296	    ngOnDestroy(): void {
297	        this.store.dispatch(ChannelActions.resetActiveChannel());
298	
299	        if (this.epgRefreshInterval) {
300	            clearInterval(this.epgRefreshInterval);
301	        }
302	
303	        if (this.progressInterval) {
304	            clearInterval(this.progressInterval);
305	        }
306	
307	        this.channelList$.complete();
308	    }
309	
310	    /**
311	     * Fetches EPG data for all channels
312	     */
313	    private fetchEpgForChannels(channels: Channel[]): void {
314	        if (!channels || channels.length === 0) {
315	            return;
316	        }
317	
318	        const channelIds = channels
319	            .map((channel) => channel?.tvg?.id?.trim() || channel?.name?.trim())
320	            .filter((id) => !!id);
321	
322	        this.epgService
323	            .getCurrentProgramsForChannels(channelIds)
324	            .subscribe((epgMap) => {
325	                this.channelEpgMap.set(epgMap);
326	            });
327	    }
328	
329	    /**
330	     * Handles channel selection from any tab
331	     */
332	    onChannelSelected(channel: Channel): void {
333	        this.store.dispatch(ChannelActions.setActiveChannel({ channel }));
334	    }
335	
336	    /**
337	     * Handles favorite toggle from favorites tab
338	     */
339	    onFavoriteToggled(event: { channel: Channel; event: MouseEvent }): void {
340	        event.event.stopPropagation();
341	        this.store.dispatch(
342	            FavoritesActions.updateFavorites({ channel: event.channel })
343	        );
344	    }
345	
346	    onHiddenGroupTitlesChanged(hiddenGroupTitles: string[]): void {
347	        const playlist = this.activePlaylist();
348	
349	        if (!playlist || playlist.serverUrl || playlist.macAddress) {
350	            return;
351	        }
352	
353	        this.store.dispatch(
354	            PlaylistActions.updatePlaylistMeta({
355	                playlist: {
356	                    _id: playlist._id,
357	                    hiddenGroupTitles,
358	                } as PlaylistMeta,
359	            })
360	        );
361	    }
