308	        let playlist: Playlist | undefined;
309	        try {
310	            playlist = (await firstValueFrom(
311	                this.playlistsService.getPlaylistById(meta._id)
312	            )) as Playlist | undefined;
313	        } catch { return []; }
314	        const favs = Array.isArray(playlist?.favorites)
315	            ? playlist.favorites.filter(isStalkerItem)
316	            : [];
317	
318	        return favs.map((fav, index) => {
319	            const ct = extractStalkerItemType(fav);
320	            const stalkerId = extractStalkerItemId(fav, meta._id, index);
321	            const poster = extractStalkerItemPoster(fav) || null;
322	            return {
323	                uid: buildCollectionUid('stalker', meta._id, stalkerId),
324	                name:
325	                    extractStalkerItemTitle(fav) ||
326	                    this.translate.instant(
327	                        'WORKSPACE.GLOBAL_FAVORITES.UNKNOWN_CHANNEL'
328	                    ),
329	                contentType: ct,
330	                sourceType: 'stalker' as const,
331	                playlistId: meta._id,
332	                playlistName:
333	                    meta.title ||
334	                    meta.filename ||
335	                    this.translate.instant(
336	                        'WORKSPACE.DASHBOARD.STALKER_PORTAL'
337	                    ),
338	                logo: ct === 'live' ? poster : null,
339	                posterUrl: ct !== 'live' ? poster : null,
340	                tvgId: ct === 'live' ? stalkerId : undefined,
341	                stalkerId,
342	                stalkerCmd: fav.cmd,
343	                stalkerPortalUrl: playlist?.portalUrl ?? playlist?.url,
344	                stalkerMacAddress: playlist?.macAddress,
345	                categoryId: fav.category_id,
346	                stalkerItem: fav,
347	                addedAt:
348	                    normalizeStalkerDate(fav.added_at) ||
349	                    new Date(0).toISOString(),
350	                position: index,
351	            };
352	        });
353	    }
354	
355	    private async getAllMeta(): Promise<PlaylistMeta[]> {
356	        return firstValueFrom(
357	            this.store.select(selectAllPlaylistsMeta).pipe(map((m) => m as PlaylistMeta[]))
358	        );
359	    }
360	
361	    private async getPlaylistMeta(id: string): Promise<PlaylistMeta | undefined> {
362	        return (await this.getAllMeta()).find((p) => p._id === id);
363	    }
364	
365	    private async getSavedOrder(): Promise<string[]> {
366	        if (!window.electron?.dbGetAppState) return [];
367	        try {
368	            const raw = await window.electron.dbGetAppState(GLOBAL_FAVORITES_ORDER_KEY);
369	            return raw ? (JSON.parse(raw) as string[]) : [];
370	        } catch { return []; }
371	    }
372	
373	    private async saveOrder(uidOrder: string[]): Promise<void> {
374	        if (!window.electron?.dbSetAppState) return;
375	        try {
376	            await window.electron.dbSetAppState(GLOBAL_FAVORITES_ORDER_KEY, JSON.stringify(uidOrder));
377	        } catch { /* ignore */ }
378	    }
379	
380	    private applyOrder(items: UnifiedCollectionItem[], savedOrder: string[]): UnifiedCollectionItem[] {
381	        if (!savedOrder.length) {
382	            return items.slice().sort((a, b) => {
383	                const pa = a.position ?? 0;
384	                const pb = b.position ?? 0;
385	                if (pa !== pb) return pa - pb;
386	                return new Date(b.addedAt ?? 0).getTime() - new Date(a.addedAt ?? 0).getTime();
387	            });
388	        }
389	        const orderMap = new Map(savedOrder.map((uid, i) => [uid, i]));
390	        const ordered: UnifiedCollectionItem[] = [];
391	        const unordered: UnifiedCollectionItem[] = [];
392	        for (const item of items) {
393	            const pos = orderMap.get(item.uid);
394	            pos != null ? ordered.push({ ...item, position: pos }) : unordered.push(item);
395	        }
396	        ordered.sort((a, b) => (a.position ?? 0) - (b.position ?? 0));
397	        unordered.sort((a, b) => new Date(b.addedAt ?? 0).getTime() - new Date(a.addedAt ?? 0).getTime());
398	        return [...ordered, ...unordered];
399	    }
400	
401	    private buildXtreamPositionUpdates(items: UnifiedCollectionItem[]) {
402	        return items
403	            .filter((item) => item.sourceType === 'xtream' && item.contentId != null)
404	            .map((item, index) => ({
405	                content_id: item.contentId!,
406	                position: index,
407	            }));
408	    }
409	
410	    private getStalkerFavoriteId(
411	        favorite: Pick<UnifiedCollectionItem, 'stalkerId' | 'uid'> | StalkerPortalItem
412	    ): string {
413	        if ('uid' in favorite) {
414	            return String(
415	                favorite.stalkerId ?? favorite.uid.split('::')[2] ?? ''
416	            ).trim();
417	        }
418	
419	        return extractStalkerItemId(favorite);
420	    }
421	}
