@use '@angular/material' as mat;

:host {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

.search-panel {
    margin-top: 10px;
    display: flex;
    justify-content: center;
    margin-bottom: -10px;
    flex-shrink: 0;
}

.search-bar {
    width: 90%;
    @include mat.form-field-density(-5);
}

:host ::ng-deep .search-bar div {
    border-radius: 20px;
}

:host ::ng-deep .search-bar div[matformfieldlineripple],
:host ::ng-deep .search-bar .mat-mdc-form-field-subscript-wrapper {
    display: none;
}

.nav-list {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 8px 8px 12px;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 48px 24px;
    text-align: center;
    color: var(--mat-sys-on-surface-variant);

    .empty-icon {
        font-size: 48px;
        height: 48px;
        width: 48px;
        margin-bottom: 16px;
        opacity: 0.5;
    }

    .empty-title {
        font-size: 14px;
        font-weight: 500;
        margin: 0 0 8px;
    }

    .empty-hint {
        font-size: 12px;
        opacity: 0.7;
        margin: 0;
        max-width: 260px;
    }
}

input.content:
@if (enrichedChannels().length > 0 || isCustomSort() === false) {
    <header class="favorites-sort-header">
        <button
            type="button"
            mat-icon-button
            [matMenuTriggerFor]="favoritesSortMenu"
            [matTooltip]="
                ('WORKSPACE.SORT_LABEL' | translate) +
                ': ' +
                (activeSortLabelKey() | translate)
            "
            [attr.aria-label]="'WORKSPACE.SORT_LABEL' | translate"
        >
            <mat-icon>sort_by_alpha</mat-icon>
        </button>
        <mat-menu #favoritesSortMenu="matMenu">
            @for (option of sortOptions; track option.mode) {
                <button
                    mat-menu-item
                    (click)="setSortMode(option.mode)"
                >
                    <mat-icon>{{ option.icon }}</mat-icon>
                    <span>{{ option.translationKey | translate }}</span>
                    @if (sortMode() === option.mode) {
                        <mat-icon class="sort-check">check</mat-icon>
                    }
                </button>
            }
        </mat-menu>
    </header>
}

<div
    class="nav-list"
    cdkDropList
    [cdkDropListDisabled]="!canDragDrop()"
    (cdkDropListDropped)="onDrop($event)"
>
    @if (enrichedChannels().length === 0) {
        <div class="empty-state">
            <mat-icon class="empty-icon">star_border</mat-icon>
            @if (hasSearchTerm()) {
                <p class="empty-title">
                    {{ 'WORKSPACE.GLOBAL_FAVORITES.NO_RESULTS' | translate }}
                </p>
                <p class="empty-hint">
                    {{
                        'WORKSPACE.GLOBAL_FAVORITES.NO_RESULTS_HINT'
                            | translate
                    }}
                </p>
            } @else {
                <p class="empty-title">
                    {{
                        'WORKSPACE.GLOBAL_FAVORITES.EMPTY_TITLE' | translate
                    }}
                </p>
                <p class="empty-hint">
                    {{ 'WORKSPACE.GLOBAL_FAVORITES.EMPTY_HINT' | translate }}
                </p>
            }
        </div>
    }

    @for (ch of enrichedChannels(); track trackByUid($index, ch)) {
        <app-channel-list-item
            [isDraggable]="canDragDrop()"
            [logo]="ch.logo"
            [name]="ch.name"
            [selected]="activeUid() === ch.uid"
            [showEpg]="true"
            [epgProgram]="ch.currentEpgProgram"
            [progressPercentage]="ch.progressPercentage"
            [showFavoriteButton]="true"
            [isFavorite]="true"
            [showProgramInfoButton]="true"
            (clicked)="onChannelClick(ch)"
            (favoriteToggled)="onFavoriteToggled(ch)"
        />
    }
</div>

