126	    readonly activeChannelForOverlay = computed((): Channel | undefined => {
127	        const detail = this.activeDetail();
128	        if (!detail) {
129	            return undefined;
130	        }
131	
132	        if (detail.channel) {
133	            return detail.channel;
134	        }
135	
