158	    readonly channelsForList = computed((): UnifiedFavoriteChannel[] =>
159	        this.items().map((item) => ({
160	            uid: item.uid,
161	            name: item.name,
162	            logo: item.logo ?? null,
163	            sourceType: item.sourceType,
164	            playlistId: item.playlistId,
165	            playlistName: item.playlistName,
166	            streamUrl: item.streamUrl,
167	            xtreamId: item.xtreamId,
168	            tvgId: item.tvgId,
169	            stalkerCmd: item.stalkerCmd,
170	            stalkerPortalUrl: item.stalkerPortalUrl,
171	            stalkerMacAddress: item.stalkerMacAddress,
172	            addedAt: item.addedAt ?? new Date(0).toISOString(),
173	            position: item.position ?? 0,
174	            contentId: item.contentId,
175	        }))
176	    );
