178	    private selectionRequestId = 0;
179	
180	    constructor() {
181	        effect(() => {
182	            const items = this.items();
183	            void this.loadEpgMap(items);
184	
185	            const activeUid = this.activeUid();
186	            if (activeUid && !items.some((item) => item.uid === activeUid)) {
187	                this.onClose();
188	            }
189	        });
190	
191	        effect(() => {
192	            const target = this.autoOpenItem();
193	            const items = this.items();
194	            if (!target || items.length === 0) {
195	                return;
196	            }
