199	                matchesOpenLiveCollectionItem(item, target)
200	            );
201	            if (!matchedItem) {
202	                return;
203	            }
204	
205	            if (this.activeUid() === matchedItem.uid) {
206	                if (this.activeDetail()) {
207	                    this.autoOpenHandled.emit();
208	                    return;
209	                }
210	
211	                if (this.isSelecting()) {
212	                    return;
213	                }
214	            }
215	
216	            void this.activateItem(matchedItem, true);
217	        });
218	
219	        const tickInterval = setInterval(
220	            () => this.progressTick.update((tick) => tick + 1),
221	            30_000
222	        );
223	        this.destroyRef.onDestroy(() => clearInterval(tickInterval));
224	    }
225	
226	    async onChannelSelected(channel: UnifiedFavoriteChannel): Promise<void> {
227	        const item = this.items().find(
228	            (candidate) => candidate.uid === channel.uid
229	        );
230	        if (item) {
231	            await this.activateItem(item);
232	        }
233	    }
234	
235	    onFavoriteToggled(channel: UnifiedFavoriteChannel): void {
236	        const item = this.items().find(
237	            (candidate) => candidate.uid === channel.uid
238	        );
239	        if (item) {
240	            this.removeItem.emit(item);
241	        }
242	    }
243	
244	    onReorder(channels: UnifiedFavoriteChannel[]): void {
245	        const reordered = channels
246	            .map((channel) =>
247	                this.items().find((candidate) => candidate.uid === channel.uid)
248	            )
249	            .filter(Boolean) as UnifiedCollectionItem[];
250	        this.reorderItems.emit(reordered);
251	    }
252	
253	    onClose(): void {
254	        this.selectionRequestId += 1;
255	        this.isSelecting.set(false);
256	        this.activeDetail.set(null);
257	        this.activeUid.set(null);
258	    }
259	
260	    private async loadEpgMap(items: UnifiedCollectionItem[]): Promise<void> {
261	        const epgMap = await this.streamResolver.loadEpgForItems(items);
262	        this.epgMap.set(epgMap);
263	    }
264	
265	    private async activateItem(
266	        item: UnifiedCollectionItem,
267	        isAutoOpen = false
268	    ): Promise<void> {
269	        if (this.activeUid() === item.uid && this.activeDetail()) {
270	            if (isAutoOpen) {
271	                this.autoOpenHandled.emit();
272	            }
273	            return;
274	        }
275	
276	        const requestId = ++this.selectionRequestId;
277	        this.activeUid.set(item.uid);
278	        this.activeDetail.set(null);
279	        this.isSelecting.set(true);
280	
281	        try {
282	            const detail =
283	                item.sourceType === 'm3u'
284	                    ? await this.streamResolver.resolveM3uPlaybackDetail(item)
285	                    : await this.streamResolver.resolveLiveDetail(item);
286	            if (requestId !== this.selectionRequestId) {
287	                return;
288	            }
289	
290	            this.activeDetail.set(detail);
291	
292	            if (detail.epgMode === 'm3u') {
293	                void this.hydrateSelectedM3uPrograms(item, detail, requestId);
294	            }
295	
296	            if (this.shouldOpenExternalPlayback(detail)) {
297	                void this.portalPlayer.openResolvedPlayback(detail.playback);
298	            }
299	
300	            try {
301	                const updatedItem =
302	                    await this.recentData.recordLivePlayback(item);
303	                if (requestId === this.selectionRequestId) {
304	                    this.itemPlayed.emit(updatedItem);
305	                }
306	            } catch {
307	                // Keep playback/EPG visible even if history persistence fails.
308	            }
309	
310	            if (requestId === this.selectionRequestId && isAutoOpen) {
311	                this.autoOpenHandled.emit();
312	            }
313	        } catch {
314	            if (requestId === this.selectionRequestId) {
315	                this.activeDetail.set(null);
316	                this.activeUid.set(null);
317	            }
318	        } finally {
319	            if (requestId === this.selectionRequestId) {
320	                this.isSelecting.set(false);
321	            }
322	        }
323	    }
324	
325	    private shouldOpenExternalPlayback(
326	        detail: ResolvedLiveCollectionDetail
327	    ): boolean {
328	        return !this.isRadioDetail(detail) && !this.portalPlayer.isEmbeddedPlayer();
329	    }
330	
331	    private isRadioDetail(
332	        detail: ResolvedLiveCollectionDetail | null | undefined
333	    ): boolean {
334	        return detail?.epgMode === 'm3u' && detail.channel?.radio === 'true';
335	    }
336	
337	    private async hydrateSelectedM3uPrograms(
338	        item: UnifiedCollectionItem,
339	        detail: ResolvedLiveCollectionDetail,
340	        requestId: number
341	    ): Promise<void> {
342	        if (detail.epgMode !== 'm3u') {
343	            return;
344	        }
345	
346	        const epgPrograms = await this.streamResolver.loadM3uProgramsForItem(
347	            item,
348	            detail.channel
349	        );
350	        if (requestId !== this.selectionRequestId) {
351	            return;
352	        }
353	
354	        this.activeDetail.update((currentDetail) => {
355	            if (!currentDetail || currentDetail.epgMode !== 'm3u') {
356	                return currentDetail;
357	            }
358	
359	            return {
360	                ...currentDetail,
361	                epgPrograms,
362	            };
363	        });
364	    }
365	}
